function TermMemoryRow({term:t,onSave}:{term:Term;onSave:(t:Term,next:any)=>void}){const [editing,setEditing]=useState(false),[value,setValue]=useState(t.term);return <div className="term-table-row"><span className="term-main"><strong>{t.term}</strong><small>{t.note||'Approved in shared term memory'}</small></span><span><i className="type-chip">{t.type}</i></span><select aria-label={`Treatment for ${t.term}`} value={t.treatment} onChange={e=>onSave(t,{treatment:e.target.value})}><option value="keep">Keep</option><option value="transliterate">Transliterate</option><option value="translate">Translate</option></select><span className="target-forms">{Object.entries(t.targets||{}).length?Object.entries(t.targets||{}).map(([l,v])=><small key={l}>{LANG_EN[l]||l}: <b>{String(v)}</b></small>):<small>No target forms saved</small>}</span><span className="term-project">Shared term memory · usage not returned</span><div className="term-row-actions">{editing?<><input value={value} onChange={e=>setValue(e.target.value)}/><button onClick={()=>{onSave(t,{term:value});setEditing(false);}}>Save</button><button onClick={()=>setEditing(false)}>Cancel</button></>:<button aria-label={`Edit ${t.term}`} onClick={()=>setEditing(true)}><Pencil size={13}/></button>}<button aria-label={`Delete ${t.term}`} onClick={()=>{if(confirm(`Remove “${t.term}” from shared term memory?`))onSave(t,{delete:true});}}><Trash2 size={13}/></button></div></div>}
function SettingsPage({config,projects,voices,settings,setPreference,saved,deleteVoice,deleteProjectAudio,deleteAll}:{config:any;projects:Project[];voices:any[];settings:any;setPreference:(k:string,v:string)=>void;saved:boolean;deleteVoice:(id:string)=>void;deleteProjectAudio:(id:string)=>void;deleteAll:()=>void}){const langs=Object.keys(config?.languages||{});return <div className="settings-column"><section className="settings-group"><div><h2>Defaults</h2><p>Preferences are saved in this browser and used for new dub forms.</p></div><div className="settings-controls"><ChipChoice label="Content type" value={settings.contentType||'lecture'} set={v=>setPreference('contentType',v)} items={['lecture','explainer','podcast','sports','business']}/><ChipChoice label="Translation style" value={settings.translationStyle||'natural_spoken'} set={v=>setPreference('translationStyle',v)} items={['natural_spoken','keep_technical','formal']}/><div className="chip-choice"><span className="field-label">Numeral style</span><div>{[['ascii','ASCII digits (1,00,000)'],['native','Native digits (१,००,०००)']].map(([v,l])=><button key={v} className={(settings.numeralStyle||'ascii')===v?'active':''} onClick={()=>setPreference('numeralStyle',v)}>{l}</button>)}</div></div>{saved&&<small className="ok-label"><Check size={13}/>Preferences saved.</small>}</div></section><section className="settings-group"><div><h2>Languages</h2><p>Language and cloning gate values are loaded from service settings.</p></div><div className="settings-languages">{langs.length?langs.map(l=><div key={l}><span>{LANG_SCRIPT[l]||config.languages[l]}</span><small>{LANG_EN[l]||config.languages[l]}</small><span className="gate-state neutral"><Check size={12}/>{config.gate_status?.[l]||config.languages?.[l]||'Configured'}</span></div>):<p className="empty-note">Language configuration is not available.</p>}</div></section><section className="settings-group"><div><h2>Safety limits</h2><p>Values enforced by the server before processing.</p></div><dl className="settings-limits"><div><dt>Daily credit limit</dt><dd>{config?.daily_credit_limit?.toLocaleString()??'Not provided'}</dd></div><div><dt>Credits remaining today</dt><dd>{config?.remaining_daily_credits?.toLocaleString()??'Not provided'}</dd></div><div><dt>Maximum video length</dt><dd>{config?.max_video_seconds?`${config.max_video_seconds} seconds`:'Not provided'}</dd></div><div><dt>Maximum credits per job</dt><dd>{config?.max_credits_per_job?.toLocaleString()??'Not provided by service settings'}</dd></div></dl></section><section className="settings-group privacy-group"><div><h2>Privacy</h2><p>Deletion calls take effect immediately and cannot be undone.</p></div><div className="privacy-actions"><div><strong>Saved voice references</strong>{voices.length?voices.map((v:any)=><p key={v.id}><span>{v.label||v.name||'Voice reference'}</span><button className="danger-button compact" onClick={()=>deleteVoice(v.id)}>Delete voice</button></p>):<small>No voice references returned by GET /api/voices.</small>}</div><div><strong>Project audio</strong>{projects.length?projects.map(p=><p key={p.id}><span>{p.name}</span><button className="danger-button compact" onClick={()=>deleteProjectAudio(p.id)}>Delete project audio</button></p>):<small>No projects with audio are available.</small>}</div><div><strong>Workspace data</strong><small>Delete all projects, uploads, voice references and generated dubs.</small><button className="danger-button" onClick={deleteAll}>Delete all my data</button></div></div></section></div>}
